package com.aivle.backend.journey;
import com.aivle.backend.common.entity.BaseEntity;import com.aivle.backend.project.entity.Project;import jakarta.persistence.*;import java.time.LocalDateTime;import lombok.*;
@Entity(name="JourneyMarketingWorkspace") @Table(name="marketing_workspaces") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class JourneyMarketingWorkspace extends BaseEntity{public enum State{DRAFT,GENERATING,READY,FAILED}@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id",nullable=false)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="idea_version_id",nullable=false)private IdeaVersion ideaVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="concept_version_id",nullable=false)private ConceptVersion conceptVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="synthesis_id",nullable=false)private InterviewSynthesis synthesis;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private State state;@Column(length=100)private String error;private LocalDateTime completedAt;public static JourneyMarketingWorkspace create(Project p,IdeaVersion idea,ConceptVersion concept,InterviewSynthesis synthesis){JourneyMarketingWorkspace v=new JourneyMarketingWorkspace();v.project=p;v.ideaVersion=idea;v.conceptVersion=concept;v.synthesis=synthesis;v.state=State.DRAFT;return v;}public void generating(){state=State.GENERATING;error=null;}public void ready(){state=State.READY;error=null;completedAt=LocalDateTime.now();}public void fail(String e){state=State.FAILED;error=e;completedAt=LocalDateTime.now();}}
